test('private dashboard renders supported records safely without browser token storage or legacy write controls',async t=>{const s=await setup(t);assert.equal(s.state.reads,1);assert.match(s.root.innerHTML,/Fictional task &lt;script&gt;/);assert.match(s.root.innerHTML,/Fictional private note/);assert.doesNotMatch(s.root.innerHTML,/<script>|brief-add-task|data-toggle|dev-organize.html|dev-account.html/);});
test('logout wipes private dashboard immediately and suppresses a pending response',async t=>{const s=await setup(t);let release;s.client.brief=()=>new Promise(resolve=>release=resolve);s.events.click({target:{closest:selector=>selector==='#private-brief-refresh'?{}:null}});while(!release)await turn();s.logout();assert.doesNotMatch(s.root.innerHTML,/Fictional private note|Fictional task/);release(structuredClone(data));for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/private-brief-login/);assert.doesNotMatch(s.root.innerHTML,/Fictional private note/);assert.equal(s.state.closed,1);});
test('failed private refresh clears stale records without reporting a fresh successful read',async t=>{const s=await setup(t);s.client.brief=async()=>{throw Error('Fictional offline read');};s.events.click({target:{closest:selector=>selector==='#private-brief-refresh'?{}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Fictional offline read/);assert.doesNotMatch(s.root.innerHTML,/Fictional private note|Saved workspace checked/);});
test('page hiding removes account and records; persisted page restoration rechecks the server',async t=>{const s=await setup(t);s.windowEvents.pagehide();assert.doesNotMatch(s.root.innerHTML,/fictional@example.test|Fictional private note/);s.windowEvents.pageshow({persisted:true});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Fictional private note/);assert.equal(s.state.reads,2);});

test('task completion requires separate review and approval; offline clears the review',async t=>{
 const s=await setup(t,{allowTaskCompletion:true});let reviews=0,writes=0;
 s.client.reviewCompletion=async()=>{reviews++;return{reviewId:'fictional-review',title:'Fictional completion',day:'2026-11-09',section:'Home',expiresAt:1000000};};
 s.client.approveCompletion=async()=>{writes++;return{completed:true};};
 const click=selector=>s.events.click({target:{closest:q=>q===selector?(selector==='[data-private-complete]'?{dataset:{privateComplete:'x'.repeat(43)}}:{}):null}});
 click('[data-private-complete]');for(let i=0;i<4;i++)await turn();assert.equal(reviews,1);assert.equal(writes,0);assert.match(s.root.innerHTML,/Approve completion/);
 s.windowEvents.offline();assert.doesNotMatch(s.root.innerHTML,/Approve completion/);click('#private-task-approve');await turn();assert.equal(writes,0);
 click('[data-private-complete]');for(let i=0;i<4;i++)await turn();click('#private-task-approve');for(let i=0;i<6;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Task marked complete/);
});
test('uncertain completion clears actions and never retries automatically',async t=>{
 const s=await setup(t,{allowTaskCompletion:true});let writes=0;s.client.reviewCompletion=async()=>({reviewId:'review',title:'Fictional',expiresAt:1000000});s.client.approveCompletion=async()=>{writes++;throw Error('Completion may have completed. Fetch latest.');};
 s.events.click({target:{closest:q=>q==='[data-private-complete]'?{dataset:{privateComplete:'x'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();s.events.click({target:{closest:q=>q==='#private-task-approve'?{}:null}});for(let i=0;i<4;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/may have completed/);assert.doesNotMatch(s.root.innerHTML,/Approve completion|Fictional private note/);
});

test('selected note text is escaped, closes explicitly and clears when the tab hides before a verified reload',async t=>{const s=await setup(t,{allowNoteRead:true});let reads=0;s.client.readNote=async()=>{reads++;return{title:'Fictional selected',body:'Private text <script>',readOnly:true,expiresAt:1000000};};const open=()=>s.events.click({target:{closest:q=>q==='[data-private-note]'?{dataset:{privateNote:'x'.repeat(43)}}:null}});assert.equal(reads,0);open();for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Private text &lt;script&gt;/);assert.doesNotMatch(s.root.innerHTML,/<script>/);s.events.click({target:{closest:q=>q==='#private-note-close'?{}:null}});assert.doesNotMatch(s.root.innerHTML,/Private text/);open();for(let i=0;i<4;i++)await turn();s.document.visibilityState='hidden';s.windowEvents.visibilitychange();assert.doesNotMatch(s.root.innerHTML,/Private text|Fictional private note|fictional@example.test/);s.document.visibilityState='visible';s.windowEvents.visibilitychange();for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Fictional private note/);assert.doesNotMatch(s.root.innerHTML,/Private text/);assert.equal(s.state.reads,2);});
test('a late selected note cannot reappear after logout',async t=>{const s=await setup(t,{allowNoteRead:true});let release;s.client.readNote=()=>new Promise(resolve=>release=resolve);s.events.click({target:{closest:q=>q==='[data-private-note]'?{dataset:{privateNote:'x'.repeat(43)}}:null}});s.logout();release({title:'Late note',body:'PRIVATE_LATE_BODY',readOnly:true,expiresAt:1000000});for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/PRIVATE_LATE_BODY|Late note/);});

async function editableNote(t){const s=await setup(t,{allowNoteRead:true,allowNoteEdit:true});s.client.readNote=async()=>({title:'Original fictional note',body:'Original fictional text',readOnly:true,expiresAt:1000000});s.click=(selector,value)=>s.events.click({target:{closest:q=>q===selector?(value?{dataset:value}:{}):null}});s.click('[data-private-note]',{privateNote:'x'.repeat(43)});for(let i=0;i<4;i++)await turn();s.click('#private-note-edit');s.events.input({target:{name:'title',value:'Updated fictional note'}});s.events.input({target:{name:'body',value:'Updated fictional text <script>'}});s.review=()=>s.events.submit({target:{id:'private-note-editor'},preventDefault(){}});return s;}
test('note editor requires separate review and approval and preserves draft text on an uncertain save',async t=>{const s=await editableNote(t);let writes=0;s.client.reviewNote=async changes=>({reviewId:'fictional-review',title:changes.title,body:changes.body,expiresAt:1000000});s.client.saveNote=async()=>{writes++;throw Error('Note save may have completed. Keep your draft.');};s.review();for(let i=0;i<4;i++)await turn();assert.equal(writes,0);assert.match(s.root.innerHTML,/Approve note save/);s.click('#private-note-approve');for(let i=0;i<4;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Updated fictional text &lt;script&gt;/);assert.match(s.root.innerHTML,/Keep your draft/);assert.doesNotMatch(s.root.innerHTML,/Approve note save/);s.review();await turn();assert.equal(writes,1);});
test('successful note save clears the submitted draft and verifies the latest list',async t=>{const s=await editableNote(t);s.client.reviewNote=async changes=>({reviewId:'fictional-review',title:changes.title,body:changes.body,expiresAt:1000000});s.client.saveNote=async()=>({saved:true});s.review();for(let i=0;i<4;i++)await turn();s.click('#private-note-approve');for(let i=0;i<6;i++)await turn();assert.match(s.root.innerHTML,/Note saved and checked/);assert.doesNotMatch(s.root.innerHTML,/private-note-editor|Updated fictional text/);assert.equal(s.state.reads,2);});
test('note drafts survive offline errors, block refresh and clear on hidden tabs',async t=>{const s=await editableNote(t);s.windowEvents.offline();assert.match(s.root.innerHTML,/Updated fictional text &lt;script&gt;/);s.click('#private-brief-refresh');await turn();assert.equal(s.state.reads,1);s.document.visibilityState='hidden';s.windowEvents.visibilitychange();assert.doesNotMatch(s.root.innerHTML,/Updated fictional text|Original fictional text|private-note-editor/);});

