test('uncertain task creation retains and locks the draft instead of retrying',async t=>{const s=await creationDraft(t);let writes=0;s.client.createTask=async()=>{writes++;throw Error('Task may have been created. Check latest.');};s.review();for(let i=0;i<4;i++)await turn();s.click('#private-task-create-approve');for(let i=0;i<4;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Fictional new task|Check latest/);assert.doesNotMatch(s.root.innerHTML,/Approve task creation/);s.review();await turn();assert.equal(writes,1);});
test('new-task drafts survive offline errors, block refresh and clear on sign-out',async t=>{const s=await creationDraft(t);s.windowEvents.offline();assert.match(s.root.innerHTML,/Fictional new task/);s.click('#private-brief-refresh');await turn();assert.equal(s.state.reads,1);s.logout();for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Fictional new task|private-task-create-form/);});

