test('hidden tabs skip passive checks and an explicit recheck verifies the current sign-in before loading',async t=>{const channel={postMessage(){},close(){}},s=await setup(t,{channel});let checks=0;s.client.check=async()=>{checks++;return{};};s.document.visibilityState='hidden';s.tick();await turn();assert.equal(checks,0);channel.onmessage({data:{type:'changed'}});s.document.visibilityState='visible';s.events.click({target:{closest:q=>q==='#private-brief-recheck'?{}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Fictional private note/);assert.equal(s.state.reads,2);assert.doesNotMatch(s.root.innerHTML,/changed in another tab/);});

test('passive checks clear the view when the cookie now belongs to a different account',async t=>{const s=await setup(t);s.client.check=async()=>({signedIn:true,user:{id:'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',email:'other@example.test'},expiresAt:1000000});s.tick();for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Fictional private note|other@example.test|fictional@example.test/);assert.match(s.root.innerHTML,/sign-in could not be verified/);});

async function noteCreationDraft(t){const s=await setup(t,{allowNoteCreate:true});s.click=selector=>s.events.click({target:{closest:q=>q===selector?{}:null}});s.click('#private-note-new');s.events.input({target:{name:'title',value:'Fictional new note'}});s.events.input({target:{name:'body',value:'Fictional new text <script>'}});s.client.reviewNewNote=async values=>({reviewId:'fictional-new-note',title:values.title.trim(),body:values.body.trim(),expiresAt:1000000});s.review=()=>s.events.submit({target:{id:'private-note-editor'},preventDefault(){}});return s;}
test('new notes require review and approval, then clear the submitted draft and refresh titles only',async t=>{const s=await noteCreationDraft(t);let writes=0;s.client.createNote=async()=>{writes++;return{created:true};};s.review();for(let i=0;i<4;i++)await turn();assert.equal(writes,0);assert.match(s.root.innerHTML,/Approve note creation/);assert.match(s.root.innerHTML,/Fictional new text &lt;script&gt;/);s.click('#private-note-approve');for(let i=0;i<6;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Note created and checked/);assert.doesNotMatch(s.root.innerHTML,/private-note-editor|Fictional new text/);assert.equal(s.state.reads,2);});
test('uncertain new-note saves retain and lock the draft without retrying',async t=>{const s=await noteCreationDraft(t);let writes=0;s.client.createNote=async()=>{writes++;throw Error('Note may have been created. Check latest.');};s.review();for(let i=0;i<4;i++)await turn();s.click('#private-note-approve');for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Fictional new text &lt;script&gt;/);assert.doesNotMatch(s.root.innerHTML,/Approve note creation/);s.review();await turn();assert.equal(writes,1);});
test('new-note drafts are retained offline, block refresh and are removed on sign-out',async t=>{const s=await noteCreationDraft(t);s.windowEvents.offline();assert.match(s.root.innerHTML,/Fictional new text &lt;script&gt;/);s.click('#private-brief-refresh');await turn();assert.equal(s.state.reads,1);s.logout();for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Fictional new text|private-note-editor/);});

async function searchableBrief(t){const s=await setup(t,{allowSearch:true});s.events.input({target:{name:'search-query',value:'Fictional'}});s.search=()=>s.events.submit({target:{id:'private-title-search'},preventDefault(){}});s.result={query:'Fictional',type:'all',section:'all',readOnly:true,providerRead:false,checkedAt:'2026-11-09T12:00:00Z',matchCount:1,omittedRecords:0,results:[{type:'note',title:'Fictional result <script>',section:'Personal Life'}]};return s;}
test('private title search runs only on submit and escapes read-only results with exact match counts',async t=>{const s=await searchableBrief(t);let searches=0;s.client.search=async values=>{searches++;assert.equal(values.query,'Fictional');return s.result;};assert.equal(searches,0);s.search();for(let i=0;i<4;i++)await turn();assert.equal(searches,1);assert.match(s.root.innerHTML,/Fictional result &lt;script&gt;/);assert.match(s.root.innerHTML,/1 matching saved item/);assert.doesNotMatch(s.root.innerHTML,/<script>/);});
test('failed or offline searches clear prior results and do not claim success',async t=>{const s=await searchableBrief(t);s.client.search=async()=>s.result;s.search();for(let i=0;i<4;i++)await turn();s.client.search=async()=>{throw Error('Fictional search unavailable');};s.search();for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/search unavailable/);assert.doesNotMatch(s.root.innerHTML,/Fictional result/);});
test('late search results cannot reappear after sign-out',async t=>{const s=await searchableBrief(t);let release;s.client.search=()=>new Promise(resolve=>release=resolve);s.search();s.logout();release(s.result);for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Fictional result|Title search results/);});

test('search results open note text only on explicit selection and still require reviewed edits',async t=>{const s=await setup(t,{allowSearch:true,allowNoteRead:true,allowNoteEdit:true});let opens=0;s.events.input({target:{name:'search-query',value:'Fictional'}});s.client.search=async()=>({query:'Fictional',type:'all',section:'all',readOnly:true,providerRead:false,checkedAt:'2026-11-09T12:00:00Z',matchCount:1,omittedRecords:0,results:[{type:'note',title:'Fictional searched note',section:'Personal Life',noteToken:'x'.repeat(43)}]});s.client.readNote=async()=>{opens++;return{title:'Fictional searched note',body:'Fictional selected text',readOnly:true,expiresAt:1000000};};s.events.submit({target:{id:'private-title-search'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(opens,0);assert.match(s.root.innerHTML,/data-private-note="x{43}"/);s.events.click({target:{closest:q=>q==='[data-private-note]'?{dataset:{privateNote:'x'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();assert.equal(opens,1);assert.match(s.root.innerHTML,/Fictional selected text|Edit note/);assert.doesNotMatch(s.root.innerHTML,/Approve note save/);});

async function searchedTask(t){const s=await setup(t,{allowSearch:true,allowTaskEdit:true,allowTaskCompletion:true});s.client.search=async()=>({query:'Fictional',type:'all',section:'all',readOnly:true,providerRead:false,checkedAt:'2026-11-09T12:00:00Z',matchCount:1,omittedRecords:0,results:[{type:'task',title:'Fictional task from search',day:'2026-11-09',section:'Home',completed:false,editToken:'e'.repeat(43),completionToken:'c'.repeat(43)}]});s.events.input({target:{name:'search-query',value:'Fictional'}});s.events.submit({target:{id:'private-title-search'},preventDefault(){}});for(let i=0;i<4;i++)await turn();return s;}
test('a searched task can enter the existing reviewed editor without a raw record ID',async t=>{const s=await searchedTask(t);s.events.click({target:{closest:q=>q==='[data-private-task-edit]'?{dataset:{privateTaskEdit:'e'.repeat(43)}}:null}});assert.match(s.root.innerHTML,/Edit this task|Fictional task from search/);let reviews=0;s.client.reviewTaskEdit=async values=>{reviews++;return{reviewId:'review',title:values.title,day:values.day,section:values.section,expiresAt:1000000};};s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(reviews,1);assert.match(s.root.innerHTML,/Approve task changes/);});
test('completion from search still requires a separate explicit review and approval',async t=>{const s=await searchedTask(t);let writes=0;s.client.reviewCompletion=async()=>({reviewId:'review',title:'Fictional task from search',day:'2026-11-09',section:'Home',expiresAt:1000000});s.client.approveCompletion=async()=>{writes++;return{completed:true};};s.events.click({target:{closest:q=>q==='[data-private-complete]'?{dataset:{privateComplete:'c'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();assert.equal(writes,0);assert.match(s.root.innerHTML,/Approve completion/);s.events.click({target:{closest:q=>q==='#private-task-approve'?{}:null}});for(let i=0;i<6;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Task marked complete/);});

test('verified private appearance applies to the dashboard and resets on sign-out',async t=>{const s=await setup(t,{allowAppearance:true});assert.equal(s.document.body.dataset.theme,'coastal');assert.equal(s.document.body.dataset.density,'compact');assert.match(s.root.innerHTML,/Saved appearance applied/);s.logout();for(let i=0;i<4;i++)await turn();assert.equal(s.document.body.dataset.theme,'neutral');assert.equal(s.document.body.dataset.density,'balanced');});
