test('a late appearance response cannot recolor the signed-out dashboard',async t=>{const s=await setup(t,{allowAppearance:true});let release;s.client.brief=()=>new Promise(resolve=>release=resolve);s.events.click({target:{closest:q=>q==='#private-brief-refresh'?{}:null}});s.logout();release(structuredClone(data));for(let i=0;i<4;i++)await turn();assert.equal(s.document.body.dataset.theme,'neutral');assert.equal(s.document.body.dataset.density,'balanced');assert.doesNotMatch(s.root.innerHTML,/Saved appearance applied|Fictional private note/);});

async function appearanceDraft(t){const s=await setup(t,{allowAppearance:true,allowAppearanceSave:true});s.client.preferences=async()=>({readOnly:false,baseTag:'b'.repeat(43),preferences:{palette:'coastal',density:'compact'},expiresAt:1000000});s.client.reviewPreferences=async values=>({reviewId:'r'.repeat(43),expiresAt:1000000,changes:[{field:'density',before:'compact',after:values.changes.density}]});s.click=selector=>s.events.click({target:{closest:q=>q===selector?{}:null}});s.click('#private-appearance-open');for(let i=0;i<4;i++)await turn();s.events.change({target:{name:'appearance-density',value:'spacious'}});s.review=()=>s.events.submit({target:{id:'private-appearance-editor'},preventDefault(){}});return s;}
