test('uncertain appearance saves retain a locked draft and never retry automatically',async t=>{const s=await appearanceDraft(t);let writes=0;s.client.savePreferences=async()=>{writes++;throw Error('Save may have completed. Keep the draft.');};s.review();for(let i=0;i<4;i++)await turn();s.click('#private-appearance-approve');for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/spacious|Keep the draft/);assert.doesNotMatch(s.root.innerHTML,/Approve appearance save/);s.review();await turn();assert.equal(writes,1);assert.equal(s.document.body.dataset.density,'compact');});
test('appearance drafts block refresh, survive offline errors and clear on sign-out',async t=>{const s=await appearanceDraft(t);s.windowEvents.offline();assert.match(s.root.innerHTML,/spacious/);s.click('#private-brief-refresh');await turn();assert.equal(s.state.reads,1);s.logout();for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/private-appearance-editor/);assert.equal(s.document.body.dataset.theme,'neutral');});
test('discard cancels appearance review and reloads the saved display without writing',async t=>{const s=await appearanceDraft(t);let cancelled=0;s.client.cancelPreferences=async()=>{cancelled++;return{cancelled:true};};s.click('#private-appearance-discard');for(let i=0;i<6;i++)await turn();assert.equal(cancelled,1);assert.doesNotMatch(s.root.innerHTML,/private-appearance-editor/);assert.equal(s.document.body.dataset.density,'compact');assert.equal(s.state.reads,2);});


function captureFocus(s){const focused=[];s.root.querySelector=selector=>({disabled:false,matches:()=>/ input$| select$/.test(selector),setAttribute(name,value){assert.equal(name,'tabindex');assert.equal(value,'-1');},focus(){focused.push(selector);}});return focused;}
test('keyboard focus enters the task editor and review heading, then confirmed save feedback without targeting approval',async t=>{const s=await setup(t,{allowTaskCreate:true}),focused=captureFocus(s);s.client.reviewNewTask=async values=>({reviewId:'fictional-review',...values,expiresAt:1000000});s.client.createTask=async()=>({created:true});const click=selector=>s.events.click({target:{closest:q=>q===selector?{}:null}});click('#private-task-new');assert.equal(focused.at(-1),'#private-task-create-form input');for(const [name,value]of [['create-title','Fictional keyboard task'],['create-day','2026-11-10']])s.events.input({target:{name,value}});s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(focused.at(-1),'#private-task-create-title');click('#private-task-create-approve');for(let i=0;i<6;i++)await turn();assert.equal(focused.at(-1),'[role="status"]');assert.ok(!focused.some(selector=>selector.includes('approve')));});
test('keyboard focus waits for async note loading and moves to readable text instead of an edit action',async t=>{const s=await setup(t,{allowNoteRead:true}),focused=captureFocus(s);let release;s.client.readNote=()=>new Promise(resolve=>release=resolve);s.events.click({target:{closest:q=>q==='[data-private-note]'?{dataset:{privateNote:'x'.repeat(43)}}:null}});assert.deepEqual(focused,[]);release({title:'Fictional selected',body:'Fictional text',readOnly:true,expiresAt:1000000});for(let i=0;i<4;i++)await turn();assert.equal(focused.at(-1),'#private-note-title');});
test('failed search focuses its error and background session checks never request focus',async t=>{const s=await setup(t,{allowSearch:true}),focused=captureFocus(s);s.client.check=async()=>({signedIn:true,user:{id:'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'},expiresAt:1000000});await s.tick();assert.deepEqual(focused,[]);s.client.search=async()=>{throw Error('Fictional unavailable');};s.events.input({target:{name:'search-query',value:'Fictional'}});s.events.submit({target:{id:'private-title-search'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(focused.at(-1),'[role="alert"]');});
test('hiding the page cancels a pending requested focus and late note response',async t=>{const s=await setup(t,{allowNoteRead:true}),focused=captureFocus(s);let release;s.client.readNote=()=>new Promise(resolve=>release=resolve);s.events.click({target:{closest:q=>q==='[data-private-note]'?{dataset:{privateNote:'x'.repeat(43)}}:null}});s.windowEvents.pagehide();release({title:'Late fictional',body:'Must not return',readOnly:true,expiresAt:1000000});for(let i=0;i<4;i++)await turn();assert.deepEqual(focused,[]);assert.doesNotMatch(s.root.innerHTML,/Late fictional/);});

test('upcoming event display includes date/time, escapes titles and clears on sign-out',async t=>{const s=await setup(t);s.client.brief=async()=>({...structuredClone(data),counts:{...data.counts,upcomingEvents:23},upcomingEvents:[{title:'Fictional future <script>',day:'2026-11-10',time:'09:30'}]});s.events.click({target:{closest:q=>q==='#private-brief-refresh'?{}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Upcoming workspace events/);assert.match(s.root.innerHTML,/Showing 1 of 23/);assert.match(s.root.innerHTML,/Fictional future &lt;script&gt;/);assert.match(s.root.innerHTML,/2026-11-10 · 09:30/);assert.doesNotMatch(s.root.innerHTML,/<script>/);s.logout();assert.doesNotMatch(s.root.innerHTML,/Fictional future|Upcoming workspace events/);});
