test('date timer leaves an active task draft untouched until an explicit user action',async t=>{let now=Date.parse('2026-11-10T04:59:00Z');const s=await setup(t,{clock:()=>now,allowTaskCreate:true});s.events.click({target:{closest:q=>q==='#private-task-new'?{}:null}});s.events.input({target:{name:'create-title',value:'Keep this fictional draft'}});const before=s.root.innerHTML;now+=120000;await s.tick();assert.equal(s.root.innerHTML,before);let proposed;s.client.reviewNewTask=async values=>{proposed=values;return{...values,reviewId:'fictional',expiresAt:now+300000};};s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(proposed.title,'Keep this fictional draft');assert.equal(proposed.day,'2026-11-09');assert.match(s.root.innerHTML,/private-brief-date-warning/);assert.equal(s.state.reads,1);});
test('date timer defers rendering while a control has focus and never requests focus itself',async t=>{let now=Date.parse('2026-11-10T04:59:00Z');const s=await setup(t,{clock:()=>now}),focused=captureFocus(s);s.document.activeElement={closest:()=>({})};now+=120000;const before=s.root.innerHTML;await s.tick();assert.equal(s.root.innerHTML,before);s.document.activeElement=null;await s.tick();assert.match(s.root.innerHTML,/private-brief-date-warning/);assert.deepEqual(focused,[]);assert.equal(s.state.reads,1);});

test('uncertain note draft has escaped selectable text without saving, clipboard access or opaque handles',async t=>{const s=await noteCreationDraft(t);let writes=0;s.client.createNote=async()=>{writes++;throw Error('Fictional uncertain note save');};s.review();for(let i=0;i<4;i++)await turn();s.click('#private-note-approve');for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Copy your draft/);assert.match(s.root.innerHTML,/<textarea id="private-draft-copy" readonly/);assert.match(s.root.innerHTML,/Title: Fictional new note\n\nFictional new text &lt;script&gt;/);assert.doesNotMatch(s.root.innerHTML,/<script>/);let focused=0,selected=0;s.root.querySelector=selector=>{assert.equal(selector,'#private-draft-copy');return{focus(){focused++;},select(){selected++;}};};s.click('#private-draft-select');assert.equal(focused,1);assert.equal(selected,1);assert.equal(writes,1);s.review();await turn();assert.equal(writes,1);s.windowEvents.pagehide();assert.doesNotMatch(s.root.innerHTML,/Copy your draft|Fictional new text/);});
test('offline task draft copy includes only editable title/date/section and selecting it does not fetch or write',async t=>{const s=await setup(t,{allowTaskCreate:true});const click=selector=>s.events.click({target:{closest:q=>q===selector?{}:null}});click('#private-task-new');s.events.input({target:{name:'create-title',value:'Fictional task <draft>'}});s.windowEvents.offline();assert.match(s.root.innerHTML,/Title: Fictional task &lt;draft&gt;\nDate: 2026-11-09\nSection: Personal Life/);assert.match(s.root.innerHTML,/Select draft text/);let selected=false;s.root.querySelector=()=>({focus(){},matches(){return true;},select(){selected=true;}});click('#private-draft-select');assert.equal(selected,true);assert.equal(s.state.reads,1);s.logout();for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/private-draft-copy|Fictional task &lt;draft&gt;/);});
