function leaving(s){let prevented=false;const event={preventDefault(){prevented=true;}};s.windowEvents.beforeunload(event);return{prevented,returnValue:event.returnValue};}
test('navigation warning protects task/event/note drafts and clears after explicit discard',async t=>{for(const kind of ['task','event','note']){const s=await setup(t,{allowTaskCreate:true,allowEventCreate:true,allowNoteCreate:true});assert.equal(leaving(s).prevented,false);const click=selector=>s.events.click({target:{closest:q=>q===selector?{}:null}});click(kind==='note'?'#private-note-new':kind==='event'?'#private-event-new':'#private-task-new');assert.deepEqual(leaving(s),{prevented:true,returnValue:''});s.client.cancelNewTask=async()=>({});s.client.cancelNewEvent=async()=>({});s.client.cancelNewNote=async()=>({});click(kind==='note'?'#private-note-discard':'#private-task-create-discard');for(let i=0;i<4;i++)await turn();assert.equal(leaving(s).prevented,false);}});
test('navigation warning protects uncertain note saves but ends after sign-out or privacy clearing',async t=>{const s=await editableNote(t);s.client.reviewNote=async changes=>({reviewId:'fixture',title:changes.title,body:changes.body,expiresAt:1000000});s.client.saveNote=async()=>{throw Error('Uncertain save');};s.review();for(let i=0;i<4;i++)await turn();s.click('#private-note-approve');for(let i=0;i<4;i++)await turn();assert.equal(leaving(s).prevented,true);s.logout();for(let i=0;i<4;i++)await turn();assert.equal(leaving(s).prevented,false);});
test('pending task status approval is protected until acknowledgement completes',async t=>{const s=await setup(t,{allowTaskCompletion:true});let release;s.client.reviewCompletion=async()=>({reviewId:'fixture',title:'Fictional',expiresAt:1000000});s.client.approveCompletion=()=>new Promise(resolve=>release=resolve);const click=selector=>s.events.click({target:{closest:q=>q===selector?(selector==='[data-private-complete]'?{dataset:{privateComplete:'x'.repeat(43)}}:{}):null}});click('[data-private-complete]');for(let i=0;i<4;i++)await turn();assert.equal(leaving(s).prevented,false);click('#private-task-approve');assert.equal(leaving(s).prevented,true);release({completed:true});for(let i=0;i<6;i++)await turn();assert.equal(leaving(s).prevented,false);});
test('privacy clearing removes the draft and its navigation warning',async t=>{const s=await setup(t,{allowTaskCreate:true});s.events.click({target:{closest:q=>q==='#private-task-new'?{}:null}});assert.equal(leaving(s).prevented,true);s.windowEvents.pagehide();assert.equal(leaving(s).prevented,false);assert.doesNotMatch(s.root.innerHTML,/private-task-create-form/);});

test('appearance drafts warn before navigation and privacy clearing removes the warning',async t=>{const s=await setup(t,{allowAppearance:true,allowAppearanceSave:true});s.client.preferences=async()=>({preferences:{palette:'coastal',density:'compact'},readOnly:false,hasSavedPreferences:true,baseTag:'b'.repeat(43),expiresAt:1000000});s.events.click({target:{closest:q=>q==='#private-appearance-open'?{}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/private-appearance-editor/);assert.equal(leaving(s).prevented,true);s.document.visibilityState='hidden';s.windowEvents.visibilitychange();assert.equal(leaving(s).prevented,false);});
test('acknowledged task creation ends the navigation warning; rejected status writes end it too',async t=>{const s=await creationDraft(t);s.client.createTask=async()=>({created:true});s.review();for(let i=0;i<4;i++)await turn();s.click('#private-task-create-approve');for(let i=0;i<6;i++)await turn();assert.equal(leaving(s).prevented,false);const status=await setup(t,{allowTaskCompletion:true});status.client.reviewCompletion=async()=>({reviewId:'fixture',title:'Fictional',expiresAt:1000000});status.client.approveCompletion=async()=>{throw Error('Unverified status write');};const click=selector=>status.events.click({target:{closest:q=>q===selector?(selector==='[data-private-complete]'?{dataset:{privateComplete:'x'.repeat(43)}}:{}):null}});click('[data-private-complete]');for(let i=0;i<4;i++)await turn();click('#private-task-approve');for(let i=0;i<4;i++)await turn();assert.equal(leaving(status).prevented,false);assert.match(status.root.innerHTML,/Unverified status write/);});

test('Command-K and Ctrl-K focus search without querying records and leave other shortcuts alone',async t=>{const s=await setup(t,{allowSearch:true});let focused=0,prevented=0;const field={disabled:false,focus(){focused++;}};s.root.querySelector=selector=>selector==='[name="search-query"]'?field:null;const event=changes=>({key:'k',metaKey:true,preventDefault(){prevented++;},...changes});s.windowEvents.keydown(event({}));s.windowEvents.keydown(event({metaKey:false,ctrlKey:true,key:'K'}));assert.equal(focused,2);assert.equal(prevented,2);assert.equal(s.state.reads,1);for(const changes of [{metaKey:false},{key:'j'},{altKey:true},{shiftKey:true},{repeat:true},{isComposing:true},{defaultPrevented:true}])s.windowEvents.keydown(event(changes));assert.equal(focused,2);field.disabled=true;s.windowEvents.keydown(event({}));assert.equal(focused,2);});
test('search shortcut cannot interrupt an editor or expose search after privacy clearing',async t=>{const s=await setup(t,{allowSearch:true,allowTaskCreate:true});let focused=0;s.root.querySelector=selector=>selector==='[name="search-query"]'?{focus(){focused++;}}:null;const event={key:'k',metaKey:true,preventDefault(){throw Error('Must not consume blocked shortcut');}};s.events.click({target:{closest:q=>q==='#private-task-new'?{}:null}});s.windowEvents.keydown(event);assert.equal(focused,0);s.windowEvents.pagehide();s.windowEvents.keydown(event);assert.equal(focused,0);});

test('new-task descriptions are reviewed exactly, escaped and retained after an uncertain save',async t=>{const s=await setup(t,{allowTaskCreate:true,allowTaskDescriptions:true});const click=selector=>s.events.click({target:{closest:q=>q===selector?{}:null}});click('#private-task-new');s.events.input({target:{name:'create-title',value:'Fictional description task'}});s.events.input({target:{name:'create-description',value:'Instructions <script>\nNext step'}});let proposed,writes=0;s.client.reviewNewTask=async fields=>{proposed=fields;return{...fields,reviewId:'fixture',expiresAt:1000000};};s.client.createTask=async()=>{writes++;throw Error('Uncertain task creation');};s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(proposed.description,'Instructions <script>\nNext step');assert.equal(writes,0);assert.match(s.root.innerHTML,/Instructions &lt;script&gt;/);assert.doesNotMatch(s.root.innerHTML,/<script>/);click('#private-task-create-approve');for(let i=0;i<4;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Description: Instructions &lt;script&gt;/);s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});await turn();assert.equal(writes,1);});
test('mismatched description review cannot expose an approval button',async t=>{const s=await setup(t,{allowTaskCreate:true,allowTaskDescriptions:true});s.events.click({target:{closest:q=>q==='#private-task-new'?{}:null}});s.events.input({target:{name:'create-title',value:'Fictional task'}});s.events.input({target:{name:'create-description',value:'Expected description'}});s.client.reviewNewTask=async fields=>({...fields,description:'Changed',reviewId:'fixture',expiresAt:1000000});s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/review could not be verified/);assert.doesNotMatch(s.root.innerHTML,/Approve task creation/);});

async function descriptionTaskDraft(t){const s=await setup(t,{allowTaskEdit:true,allowTaskDescriptionEdit:true});s.client.brief=async()=>({...structuredClone(data),dueTasks:[{...data.dueTasks[0],editToken:'x'.repeat(43)}]});s.click=selector=>s.events.click({target:{closest:q=>q===selector?(selector==='[data-private-task-edit]'?{dataset:{privateTaskEdit:'x'.repeat(43)}}:{}):null}});s.client.readTaskEdit=async()=>({title:data.dueTasks[0].title,day:data.day,section:'Work',description:'Fictional original instructions',expiresAt:1000000});s.click('#private-brief-refresh');for(let i=0;i<4;i++)await turn();s.click('[data-private-task-edit]');for(let i=0;i<4;i++)await turn();return s;}
test('task description editor reads only after selection, reviews exact text and retains uncertain drafts',async t=>{const s=await descriptionTaskDraft(t);assert.match(s.root.innerHTML,/Fictional original instructions/);s.events.input({target:{name:'create-description',value:'Edited <script> instructions'}});let writes=0;s.client.reviewTaskEdit=async fields=>({...fields,reviewId:'fixture',expiresAt:1000000});s.client.saveTaskEdit=async()=>{writes++;throw Error('Uncertain description edit');};s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Edited &lt;script&gt; instructions/);assert.equal(writes,0);s.click('#private-task-create-approve');for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Description: Edited &lt;script&gt; instructions/);s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});await turn();assert.equal(writes,1);});
test('task description edit rejects changed review text and pending reads cannot survive sign-out',async t=>{const s=await descriptionTaskDraft(t);s.client.reviewTaskEdit=async fields=>({...fields,description:'Unexpected',reviewId:'fixture',expiresAt:1000000});s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Approve task changes/);s.client.cancelTaskEdit=async()=>({cancelled:true});s.click('#private-task-create-discard');for(let i=0;i<4;i++)await turn();let release;s.client.readTaskEdit=()=>new Promise(resolve=>release=resolve);s.click('[data-private-task-edit]');s.logout();release({title:data.dueTasks[0].title,day:data.day,section:'Work',description:'LATE_DESCRIPTION_EDIT',expiresAt:1000000});for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/LATE_DESCRIPTION_EDIT|private-task-create-form/);});

async function checklistDraft(t){const s=await setup(t,{allowTaskCreate:true,allowTaskSubtasks:true});s.click=selector=>s.events.click({target:{closest:q=>q===selector?{}:null}});s.click('#private-task-new');s.events.input({target:{name:'create-title',value:'Fictional checklist task'}});s.events.input({target:{name:'create-subtaskText',value:' First <script> step \n\n Second step '}});s.review=()=>s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});return s;}
test('checklist review parses lines, drops blanks, escapes text and retains raw steps after uncertain save',async t=>{const s=await checklistDraft(t);let proposal,writes=0;s.client.reviewNewTask=async fields=>{proposal=fields;return{...fields,subtasks:fields.subtasks.map(title=>({title,done:false})),reviewId:'fixture',expiresAt:1000000};};s.client.createTask=async()=>{writes++;throw Error('Uncertain checklist creation');};s.review();for(let i=0;i<4;i++)await turn();assert.deepEqual(Array.from(proposal.subtasks),['First <script> step','Second step']);assert.equal(proposal.subtaskText,undefined);assert.equal(writes,0);assert.match(s.root.innerHTML,/First &lt;script&gt; step/);s.click('#private-task-create-approve');for(let i=0;i<4;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Checklist steps:/);assert.doesNotMatch(s.root.innerHTML,/Approve task creation/);});
test('oversized checklists stop before requests and changed review steps cannot be approved',async t=>{const s=await checklistDraft(t);let reviews=0;s.client.reviewNewTask=async fields=>{reviews++;return{...fields,subtasks:[{title:'Changed',done:false}],reviewId:'fixture',expiresAt:1000000};};s.events.input({target:{name:'create-subtaskText',value:Array(21).fill('Step').join('\n')}});s.review();await turn();assert.equal(reviews,0);assert.match(s.root.innerHTML,/at most 20 checklist steps/);s.events.input({target:{name:'create-subtaskText',value:'Expected step'}});s.review();for(let i=0;i<4;i++)await turn();assert.equal(reviews,1);assert.match(s.root.innerHTML,/Checklist review could not be verified/);assert.doesNotMatch(s.root.innerHTML,/Approve task creation/);});

async function checklistEditDraft(t,{unavailable=false,titles=false,structure=false}={}){const s=await setup(t,{allowTaskEdit:true,allowTaskDescriptionEdit:true,allowTaskChecklistEdit:true,allowTaskChecklistTitles:titles||structure,allowTaskChecklistStructure:structure});s.client.brief=async()=>({...structuredClone(data),dueTasks:[{...data.dueTasks[0],editToken:'x'.repeat(43)}]});s.click=selector=>s.events.click({target:{closest:q=>q===selector?(selector==='[data-private-task-edit]'?{dataset:{privateTaskEdit:'x'.repeat(43)}}:{}):null}});s.client.readTaskEdit=async()=>({title:data.dueTasks[0].title,day:data.day,section:'Work',description:'Fictional description',subtasks:unavailable?null:[{title:'First <script>',done:false},{title:'Second',done:true}],expiresAt:1000000});s.click('#private-brief-refresh');for(let i=0;i<4;i++)await turn();s.click('[data-private-task-edit]');for(let i=0;i<4;i++)await turn();s.review=()=>s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});return s;}
test('checklist completion editor reviews booleans only and retains uncertain state without retries',async t=>{const s=await checklistEditDraft(t);assert.match(s.root.innerHTML,/First &lt;script&gt;/);s.events.change({target:{name:'create-subtask-0',checked:true}});s.events.change({target:{name:'create-subtask-1',checked:false}});let proposal,writes=0;s.client.reviewTaskEdit=async fields=>{proposal=fields;return{...fields,reviewId:'fixture',subtasks:[{title:'First <script>',done:true},{title:'Second',done:false}],expiresAt:1000000};};s.client.saveTaskEdit=async()=>{writes++;throw Error('Uncertain checklist edit');};s.review();for(let i=0;i<4;i++)await turn();assert.deepEqual(Array.from(proposal.subtaskStates),[true,false]);assert.equal(proposal.subtaskLabels,undefined);assert.equal(proposal.checklistUnavailable,undefined);assert.equal(writes,0);assert.match(s.root.innerHTML,/Checklist completion after saving/);assert.match(s.root.innerHTML,/First &lt;script&gt; · Completed/);s.click('#private-task-create-approve');for(let i=0;i<4;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Checklist states:/);s.review();await turn();assert.equal(writes,1);});
test('unsupported saved checklists omit status proposals while retaining normal task editing',async t=>{const s=await checklistEditDraft(t,{unavailable:true});assert.match(s.root.innerHTML,/checklist cannot be edited here/);assert.doesNotMatch(s.root.innerHTML,/create-subtask-0/);let proposal;s.client.reviewTaskEdit=async fields=>{proposal=fields;return{...fields,reviewId:'fixture',expiresAt:1000000};};s.review();for(let i=0;i<4;i++)await turn();assert.equal(proposal.subtaskStates,undefined);assert.equal(proposal.checklistUnavailable,undefined);assert.match(s.root.innerHTML,/Approve task changes/);});
test('mismatched checklist statuses in review cannot be approved',async t=>{const s=await checklistEditDraft(t);s.client.reviewTaskEdit=async fields=>({...fields,reviewId:'fixture',subtasks:[{title:'First <script>',done:true},{title:'Second',done:true}],expiresAt:1000000});s.review();for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Checklist changes could not be verified/);assert.doesNotMatch(s.root.innerHTML,/Approve task changes/);});

test('task completion/reopening review explains remaining steps without changing or automatically approving anything',async t=>{for(const reopening of [false,true]){const s=await setup(t,{allowTaskCompletion:true,allowTaskReopen:true});s.client.reviewCompletion=async()=>({title:'Fictional task',reviewId:'fixture',expiresAt:1000000,reopening,checklist:{total:3,open:2}});let writes=0;s.client.approveCompletion=async()=>{writes++;return{completed:true};};s.events.click({target:{closest:q=>q===(reopening?'[data-private-reopen]':'[data-private-complete]')?{dataset:{privateReopen:'x'.repeat(43),privateComplete:'x'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/2 of 3 checklist steps remain open/);assert.match(s.root.innerHTML,reopening?/Reopening the task leaves each step unchanged/:/Completing the task leaves each step unchanged/);assert.equal(writes,0);}});
