test('step title edits send reviewed titles without local metadata and retain uncertain text',async t=>{const s=await checklistEditDraft(t,{titles:true});assert.match(s.root.innerHTML,/Step 1 title/);s.events.input({target:{name:'create-subtask-title-0',value:' Revised <script> title '}});let proposed;s.client.reviewTaskEdit=async fields=>{proposed=fields;return{...fields,subtasks:[{title:'Revised <script> title',done:false},{title:'Second',done:true}],reviewId:'fixture',expiresAt:1000000};};s.client.saveTaskEdit=async()=>{throw Error('Uncertain step rename');};s.review();for(let i=0;i<4;i++)await turn();assert.deepEqual(Array.from(proposed.subtaskTitles),[' Revised <script> title ','Second']);assert.equal(proposed.subtaskLabels,undefined);assert.match(s.root.innerHTML,/Revised &lt;script&gt; title · Open/);s.click('#private-task-create-approve');for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Checklist states:/);assert.match(s.root.innerHTML,/Revised &lt;script&gt; title/);});
