test('selected event editor loads location/details only after explicit edit and reviews exact changes',async t=>{const s=await setup(t,{allowEventEdit:true,allowEventDetails:true});let reads=0;s.client.brief=async()=>({...structuredClone(data),counts:{...data.counts,eventsToday:1},eventsToday:[{title:'Fictional detailed event',time:'09:30',eventEditToken:'e'.repeat(43)}]});s.client.readEventEdit=async()=>{reads++;return{title:'Fictional detailed event',day:data.day,time:'09:30',end_time:'10:30',section:'Calendar',location:'Original room',description:'Original detail',expiresAt:1000000};};const click=selector=>s.events.click({target:{closest:q=>q===selector?(selector==='[data-private-event-edit]'?{dataset:{privateEventEdit:'e'.repeat(43)}}:{}):null}});click('#private-brief-refresh');for(let i=0;i<4;i++)await turn();assert.equal(reads,0);click('[data-private-event-edit]');for(let i=0;i<4;i++)await turn();assert.equal(reads,1);assert.match(s.root.innerHTML,/Original room/);assert.match(s.root.innerHTML,/Original detail/);s.events.input({target:{name:'create-location',value:'Revised room'}});let proposed;s.client.reviewEventEdit=async fields=>{proposed=fields;return{...fields,section:'Calendar',reviewId:'fixture',expiresAt:1000000};};s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(proposed.location,'Revised room');assert.equal(proposed.description,'Original detail');assert.equal(proposed.end_time,'10:30');assert.match(s.root.innerHTML,/Approve event changes/);});

async function openableEvent(t){const s=await setup(t,{allowEventEdit:true,allowEventDetails:true,allowSearch:true});s.client.brief=async()=>({...structuredClone(data),eventsToday:[{title:'Fictional readable event',time:'09:30',eventEditToken:'e'.repeat(43)}]});s.click=selector=>s.events.click({target:{closest:q=>q===selector?(selector==='[data-private-event-open]'?{dataset:{privateEventOpen:'e'.repeat(43)}}:selector==='[data-private-browse]'?{dataset:{privateBrowse:'event'}}:{}):null}});s.click('#private-brief-refresh');for(let i=0;i<4;i++)await turn();s.client.readEventEdit=async()=>({title:'Fictional readable event',day:data.day,time:'09:30',end_time:'10:30',section:'Calendar',location:'Fictional room <script>',description:'READ_ONLY_EVENT_TEXT',expiresAt:1000000});return s;}
test('read-only event panel opens explicitly, escapes text and closes with Escape without an editor',async t=>{const s=await openableEvent(t);assert.doesNotMatch(s.root.innerHTML,/READ_ONLY_EVENT_TEXT/);s.click('[data-private-event-open]');for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/private-event-details-title/);assert.match(s.root.innerHTML,/Fictional room &lt;script&gt;/);assert.match(s.root.innerHTML,/READ_ONLY_EVENT_TEXT/);assert.doesNotMatch(s.root.innerHTML,/id="private-task-create-form"/);s.windowEvents.keydown({key:'Escape',preventDefault(){}});assert.doesNotMatch(s.root.innerHTML,/READ_ONLY_EVENT_TEXT/);});
test('event browsing opens read-only details and sign-out suppresses late event text',async t=>{const s=await openableEvent(t);s.client.search=async fields=>({...fields,readOnly:true,providerRead:false,matchCount:1,checkedAt:'2026-11-09T12:00:00Z',expiresAt:1000000,results:[{type:'event',title:'Fictional readable event',day:data.day,time:'09:30',section:'Calendar',eventEditToken:'e'.repeat(43)}]});s.click('[data-private-browse]');for(let i=0;i<4;i++)await turn();s.click('[data-private-event-open]');for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/READ_ONLY_EVENT_TEXT/);s.click('#private-event-details-close');let release;s.client.readEventEdit=()=>new Promise(resolve=>release=resolve);s.click('[data-private-event-open]');s.logout();release({title:'Fictional readable event',day:data.day,time:'09:30',end_time:'',section:'Calendar',location:'LATE_LOCATION',description:'LATE_EVENT_TEXT',expiresAt:1000000});for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/LATE_EVENT_TEXT|LATE_LOCATION/);});
test('all-day creation reviews a selected date without misleading midnight times and preserves the timed draft on toggling',async t=>{const s=await setup(t,{allowEventCreate:true,allowEventDetails:true,allowAllDayEvents:true});s.events.click({target:{closest:q=>q==='#private-event-new'?{}:null}});s.events.input({target:{name:'create-title',value:'Fictional all-day event'}});s.events.change({target:{name:'create-time',value:'11:30'}});s.events.change({target:{name:'create-all_day',checked:true}});s.events.change({target:{name:'create-all_day',checked:false}});assert.match(s.root.innerHTML,/value="11:30"/);s.events.change({target:{name:'create-all_day',checked:true}});let proposed;s.client.reviewNewEvent=async fields=>{proposed=fields;return{...fields,section:'Calendar',reviewId:'fixture',expiresAt:1000000};};s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(proposed.all_day,true);assert.equal(proposed.time,'00:00');assert.equal(proposed.end_time,'');assert.match(s.root.innerHTML,/ · All day/);assert.doesNotMatch(s.root.innerHTML,/00:00 New York time/);});

