test('Recently Deleted controls are default-off; explicit mode reviews escaped titles without writes',async t=>{const off=await setup(t);assert.doesNotMatch(off.root.innerHTML,/private-records-open/);const s=await setup(t,{allowRecentlyDeleted:true});assert.match(s.root.innerHTML,/Recently Deleted/);let writes=0;s.client.reviewRecord=async()=>({reviewId:'r'.repeat(43),title:'Fictional <script> removal',type:'note',section:'Personal Life',restoring:false,retentionDays:90,expiresAt:100000});s.client.saveRecord=async()=>{writes++;return{saved:true,restored:false};};s.events.click({target:{closest:q=>q==='[data-private-record-review]'?{dataset:{privateRecordReview:'t'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();assert.equal(writes,0);assert.match(s.root.innerHTML,/Move this item to Recently Deleted\?/);assert.match(s.root.innerHTML,/Fictional &lt;script&gt; removal/);assert.doesNotMatch(s.root.innerHTML,/<script>/);s.events.click({target:{closest:q=>q==='#private-record-approve'?{}:null}});s.events.click({target:{closest:q=>q==='#private-record-approve'?{}:null}});for(let i=0;i<8;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Item moved to Recently Deleted/);});
test('removed-item browsing is title-only, paginated and restoration requires its own approval',async t=>{const s=await setup(t,{allowRecentlyDeleted:true});const offsets=[];s.client.deletedRecords=async offset=>{offsets.push(offset);return{retentionDays:90,offset,limit:50,matchCount:51,expiresAt:100000,records:[{title:'Fictional removed note',type:'note',section:'Personal Life',deletedAt:'2026-11-09T12:00:00Z',recordToken:'t'.repeat(43)}]};};s.client.reviewRecord=async()=>({reviewId:'r'.repeat(43),title:'Fictional removed note',type:'note',section:'Personal Life',restoring:true,retentionDays:90,expiresAt:100000});let writes=0;s.client.saveRecord=async()=>{writes++;return{saved:true,restored:true};};const click=id=>s.events.click({target:{closest:q=>q===id?{}:null}});click('#private-records-open');for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Review restore/);click('#private-records-next');for(let i=0;i<4;i++)await turn();assert.deepEqual(offsets,[0,50]);s.events.click({target:{closest:q=>q==='[data-private-record-review]'?{dataset:{privateRecordReview:'t'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/Restore this item\?/);assert.equal(writes,0);click('#private-record-approve');for(let i=0;i<8;i++)await turn();assert.equal(writes,1);assert.match(s.root.innerHTML,/Item restored/);});
