test('uncertain recovery save clears stale records and never offers automatic retry',async t=>{const s=await setup(t,{allowRecentlyDeleted:true});s.client.reviewRecord=async()=>({reviewId:'r'.repeat(43),title:'Fictional removal',type:'note',section:'Personal Life',restoring:false,retentionDays:90,expiresAt:100000});let writes=0;s.client.saveRecord=async()=>{writes++;throw Error('Change may have completed. Fetch latest.');};const click=selector=>s.events.click({target:{closest:q=>q===selector?(selector==='[data-private-record-review]'?{dataset:{privateRecordReview:'t'.repeat(43)}}:{}):null}});click('[data-private-record-review]');for(let i=0;i<4;i++)await turn();click('#private-record-approve');for(let i=0;i<4;i++)await turn();click('#private-record-approve');assert.equal(writes,1);assert.match(s.root.innerHTML,/Change may have completed/);assert.doesNotMatch(s.root.innerHTML,/Fictional private note|Approve removal/);});

