test('undated task creation sends an explicit blank date and reviews No due date without writing',async t=>{const s=await setup(t,{allowUndatedTasks:true,allowTaskCreate:true});assert.match(s.root.innerHTML,/No due date tasks/);let proposals=[],writes=0;s.client.reviewNewTask=async values=>{proposals.push(values);return{...values,reviewId:'fictional-review',expiresAt:100000};};s.client.createTask=async()=>{writes++;return{created:true};};const click=id=>s.events.click({target:{closest:q=>q===id?{}:null}});click('#private-task-new');assert.match(s.root.innerHTML,/Leave the task date blank/);assert.doesNotMatch(s.root.innerHTML,/name="create-day"[^>]* required/);s.events.input({target:{name:'create-title',value:'Fictional no date task'}});s.events.input({target:{name:'create-day',value:''}});await s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(proposals[0].day,'');assert.match(s.root.innerHTML,/No due date/);assert.equal(writes,0);click('#private-task-create-approve');for(let i=0;i<8;i++)await turn();assert.equal(writes,1);});
test('undated tasks can open their selected editor and have a reviewed date added',async t=>{const s=await setup(t,{allowUndatedTasks:true,allowTaskEdit:true,allowTaskDescriptionEdit:true});s.client.brief=async()=>({...structuredClone(data),undatedTasks:[{title:'Fictional undated editor',day:'',section:'Home',editToken:'t'.repeat(43)}],counts:{...data.counts,undatedTasks:1}});s.events.click({target:{closest:q=>q==='#private-brief-refresh'?{}:null}});for(let i=0;i<4;i++)await turn();s.client.readTaskEdit=async()=>({title:'Fictional undated editor',day:'',section:'Home',description:'Preserve fictional text',expiresAt:100000});s.client.reviewTaskEdit=async values=>({...values,reviewId:'fictional-review',expiresAt:100000});s.events.click({target:{closest:q=>q==='[data-private-task-edit]'?{dataset:{privateTaskEdit:'t'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/value="Fictional undated editor"/);s.events.input({target:{name:'create-day',value:'2026-11-10'}});await s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.match(s.root.innerHTML,/2026-11-10 · Home/);assert.match(s.root.innerHTML,/Approve task changes/);});

