test('smart task entry is local, escaped, editable and anchored to New York today rather than the browsed day',async t=>{const s=await setup(t,{allowSmartTaskEntry:true,allowTaskCreate:true,allowTaskPriority:true,allowUndatedTasks:true,allowBriefDates:true,clock:()=>Date.parse('2026-11-10T17:00:00Z')});let reviews=0;s.client.reviewNewTask=async()=>{reviews++;throw Error('No review was requested');};s.client.brief=async day=>({...structuredClone(data),day:day||data.day,selectedDate:true,currentRecords:true,undatedTasks:[],counts:{...data.counts,undatedTasks:0},expiresAt:Date.parse('2026-11-10T18:00:00Z')});s.events.input({target:{name:'brief-date',value:'2000-01-01'}});await s.events.submit({target:{id:'private-brief-date-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();s.events.input({target:{name:'smart-task-text',value:'<script>Call</script> due tomorrow priority High'}});await s.events.submit({target:{id:'private-smart-task-form'},preventDefault(){}});await turn();assert.equal(reviews,0);assert.match(s.root.innerHTML,/value="&lt;script&gt;Call&lt;\/script&gt;"/);assert.doesNotMatch(s.root.innerHTML,/<script>/);assert.match(s.root.innerHTML,/value="2026-11-11"/);assert.match(s.root.innerHTML,/<option selected>High/);assert.match(s.root.innerHTML,/Task details prepared locally/);assert.match(s.root.innerHTML,/name="smart-task-text"[^>]*value=""/);});
test('unrecognized quick-task text remains intact without opening or saving a partial task',async t=>{const s=await setup(t,{allowSmartTaskEntry:true,allowTaskCreate:true,allowTaskPriority:true,allowUndatedTasks:true,clock:()=>Date.parse('2026-11-10T17:00:00Z')});s.events.input({target:{name:'smart-task-text',value:'Fictional task due someday'}});await s.events.submit({target:{id:'private-smart-task-form'},preventDefault(){}});await turn();assert.match(s.root.innerHTML,/not recognized/);assert.match(s.root.innerHTML,/value="Fictional task due someday"/);assert.doesNotMatch(s.root.innerHTML,/id="private-task-create-form"/);});
test('unprepared smart-task text warns on navigation and clears on page hiding',async t=>{const s=await setup(t,{allowSmartTaskEntry:true,allowTaskCreate:true,allowTaskPriority:true,allowUndatedTasks:true});s.events.input({target:{name:'smart-task-text',value:'Fictional private quick capture'}});let warned=false;s.windowEvents.beforeunload({preventDefault(){warned=true;}});assert.equal(warned,true);s.windowEvents.pagehide();assert.doesNotMatch(s.root.innerHTML,/Fictional private quick capture/);s.windowEvents.pageshow({persisted:true});for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/Fictional private quick capture/);});

