const copyEventOptions={...calendarOptions,allowEventCreate:true,allowAllDayEvents:true,allowEventRanges:true};
async function openCopyEvent(s){s.client.readEventEdit=async()=>({title:'Fictional workspace event',day:'2026-11-10',time:'09:00',end_time:'10:00',end_day:'',all_day:false,section:'Calendar',location:'Fictional room',description:'Fictional complete details',expiresAt:copyEventOptions.clock()+100000});s.events.click({target:{closest:q=>q==='[data-private-event-open]'?{dataset:{privateEventOpen:'E'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();}
const clickEventCopy=s=>s.events.click({target:{closest:q=>q==='#private-event-copy'?{}:null}});
