test('opened task checklist filters only displayed steps without another read and keeps partial progress honest',async t=>{const s=await selectedCopyTask(t,{subtasks:[{title:'Completed fictional step',done:true},{title:'Open fictional step',done:false}],subtaskCount:3,omittedSubtasks:1});let reads=0;s.client.readTask=async()=>{reads++;throw Error('No further read allowed');};const filter=value=>s.events.click({target:{closest:q=>q==='[data-private-checklist-filter]'?{dataset:{privateChecklistFilter:value}}:null}});assert.match(s.root.innerHTML,/1 of 2 displayed steps complete/);assert.match(s.root.innerHTML,/Progress covers displayed steps only/);filter('open');assert.match(s.root.innerHTML,/Showing 1 open step/);assert.match(s.root.innerHTML,/<strong>Open fictional step<\/strong>/);assert.doesNotMatch(s.root.innerHTML,/<strong>Completed fictional step<\/strong>/);filter('completed');assert.match(s.root.innerHTML,/Showing 1 completed step/);assert.match(s.root.innerHTML,/<strong>Completed fictional step<\/strong>/);assert.doesNotMatch(s.root.innerHTML,/<strong>Open fictional step<\/strong>/);filter('all');assert.match(s.root.innerHTML,/Showing 2 displayed step/);assert.match(s.root.innerHTML,/data-private-checklist-filter="all" aria-pressed="true"/);assert.equal(reads,0);});
test('checklist filtering handles empty matches, resets on reopen and never changes copied checklist coverage',async t=>{const s=await selectedCopyTask(t,{subtasks:[{title:'Open only fictional step',done:false}],subtaskCount:1,omittedSubtasks:0}),click=(selector,dataset={})=>s.events.click({target:{closest:q=>q===selector?{dataset}:null}});click('[data-private-checklist-filter]',{privateChecklistFilter:'completed'});assert.match(s.root.innerHTML,/No completed steps among the displayed checklist/);click('#private-task-copy');s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});await turn();assert.match(s.root.innerHTML,/Open only fictional step/);assert.match(s.root.innerHTML,/private-task-create-form/);const reopened=await selectedCopyTask(t);const filter=value=>reopened.events.click({target:{closest:q=>q==='[data-private-checklist-filter]'?{dataset:{privateChecklistFilter:value}}:null}});filter('open');reopened.events.click({target:{closest:q=>q==='#private-task-details-close'?{}:null}});reopened.events.click({target:{closest:q=>q==='[data-private-task-open]'?{dataset:{privateTaskOpen:'Q'.repeat(43)}}:null}});for(let i=0;i<4;i++)await turn();assert.match(reopened.root.innerHTML,/data-private-checklist-filter="all" aria-pressed="true"/);});
test('a filtered task copy still includes the complete displayed checklist and reopens every copied step',async t=>{const s=await selectedCopyTask(t);s.events.click({target:{closest:q=>q==='[data-private-checklist-filter]'?{dataset:{privateChecklistFilter:'open'}}:null}});s.events.click({target:{closest:q=>q==='#private-task-copy'?{}:null}});let proposal;s.client.reviewNewTask=async fields=>{proposal=fields;return{...fields,subtasks:fields.subtasks.map(title=>({title,done:false})),reviewId:'R'.repeat(43),expiresAt:1000000};};s.events.submit({target:{id:'private-task-create-form'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.deepEqual(Array.from(proposal.subtasks),['First copied step','Second copied step']);assert.match(s.root.innerHTML,/First copied step · Open/);assert.match(s.root.innerHTML,/Second copied step · Open/);});
test('expired checklist views cannot be filtered or retain private step text',async t=>{let now=1;const s=await selectedCopyTask(t,{}, {clock:()=>now});now=1000000;s.events.click({target:{closest:q=>q==='[data-private-checklist-filter]'?{dataset:{privateChecklistFilter:'open'}}:null}});assert.match(s.root.innerHTML,/Task view expired/);assert.doesNotMatch(s.root.innerHTML,/First copied step|Second copied step|id="private-task-details-title"/);});
test('password recovery link appears only on an explicitly enabled signed-out workspace',async t=>{for(const enabled of [false,true]){const s=await setup(t,{allowPasswordRecovery:enabled});assert.doesNotMatch(s.root.innerHTML,/Forgot your password/);s.logout();for(let i=0;i<4;i++)await turn();assert.equal(s.root.innerHTML.includes('href="/auth/recovery/"'),enabled);assert.match(s.root.innerHTML,/>Email<input/);}});
test('saved accounts stay closed until chosen and pending results cannot survive sign-out',async t=>{const s=await setup(t,{allowSavedFinanceRead:true});let reads=0,release;s.client.readSavedFinance=()=>{reads++;return new Promise(r=>release=r);};assert.match(s.root.innerHTML,/Saved financial accounts/);assert.equal(reads,0);s.events.click({target:{closest:q=>q==='#private-finance-load'?{}:null}});assert.equal(reads,1);s.logout();release({});for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/private-saved-finance-panel/);});

test('a late saved-account result preserves a note draft and keeps amount reveal blocked until the draft is resolved',async t=>{const now=Date.parse('2026-11-14T18:00:00Z'),s=await setup(t,{allowSavedFinanceRead:true,allowNoteCreate:true,clock:()=>now}),panel={innerHTML:'',contains:()=>false};s.root.querySelector=q=>q==='#private-saved-finance-panel'?panel:null;let release;s.client.readSavedFinance=()=>new Promise(r=>release=r);s.events.click({target:{closest:q=>q==='#private-finance-load'?{}:null}});s.events.click({target:{closest:q=>q==='#private-note-new'?{}:null}});s.events.input({target:{name:'title',value:'Keep this note while accounts arrive'}});release({source:'Saved Chase account copies',readOnly:true,snapshot:true,providerRead:false,currency:'USD',limit:10,checkedAt:new Date(now).toISOString(),expiresAt:now+300000,accounts:[{name:'Fictional account',type:'depository',subtype:'checking',currentMinor:123456,availableMinor:null,savedAt:new Date(now).toISOString()}]});for(let i=0;i<4;i++)await turn();assert.match(panel.innerHTML,/id="private-finance-amounts" disabled/);assert.doesNotMatch(panel.innerHTML,/1,234.56/);s.events.click({target:{closest:q=>q==='#private-finance-amounts'?{}:null}});assert.doesNotMatch(panel.innerHTML,/1,234.56/);let reviewed;s.client.reviewNewNote=async values=>{reviewed=values;return{reviewId:'N'.repeat(43),...values,expiresAt:now+300000};};s.events.submit({target:{id:'private-note-editor'},preventDefault(){}});for(let i=0;i<4;i++)await turn();assert.equal(reviewed.title,'Keep this note while accounts arrive');});

test('transaction panel never reads automatically and clears pending data on account sign-out',async t=>{const s=await setup(t,{allowSavedFinanceRead:true,allowSavedTransactionsRead:true});let reads=0,release;s.client.readSavedTransactions=()=>{reads++;return new Promise(r=>release=r);};assert.equal(reads,0);assert.match(s.root.innerHTML,/View saved transactions/);s.events.click({target:{closest:q=>q==='#private-transactions-load'?{}:null}});assert.equal(reads,1);s.logout();release({});for(let i=0;i<4;i++)await turn();assert.doesNotMatch(s.root.innerHTML,/private-saved-transactions-panel/);});
